const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:8px;color:var(--ink);font:13px/1.45 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;background:transparent}\n.card *{box-sizing:border-box}\n.view{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.head{display:flex;align-items:center;gap:6px;min-width:0;flex:none}\n.ttl{flex:1;min-width:0;display:flex;flex-direction:column;line-height:1.25}\n.ttl b{font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.ttl span{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn{font:inherit;font-size:12px;line-height:1.2;color:var(--ink);background:var(--button-paper,var(--panel-paper));border:1px solid var(--line);border-radius:8px;padding:5px 10px;min-height:28px;cursor:pointer;white-space:nowrap;flex:none}\n.btn:disabled{opacity:.55;cursor:default}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.sm{padding:4px 8px}\n.btn.ico{width:28px;padding:0;font-size:18px}\n.btn.wide{width:100%}\n.btn.strong{border-color:var(--ink);font-weight:700}\n.btn.link{background:transparent;border-color:transparent;color:var(--muted);text-decoration:underline;padding-left:0}\n.err{flex:none;font-size:12px;padding:4px 8px;border:1px solid var(--ink);border-radius:8px;background:var(--soft);color:var(--ink)}\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto}\n.foot{flex:none;display:flex;gap:6px}\n.foot.two .btn{flex:1}\n.empty{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;justify-content:center;gap:4px;padding:8px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);font-size:12px}\n.empty b{color:var(--ink);font-size:13px}\n.list{display:flex;flex-direction:column;gap:6px}\n.list .empty{flex:none;min-height:80px}\n.vrow{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"n c\" \"m c\";column-gap:6px;align-items:center;text-align:left;font:inherit;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;padding:7px 9px;cursor:pointer;width:100%;flex:none}\n.vrow.has{border-left:3px solid var(--accent)}\n.vn{grid-area:n;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.vm{grid-area:m;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.chev{grid-area:c;color:var(--muted);font-size:18px}\n\n.sets{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px}\n.set{flex:none;display:flex;flex-direction:column;min-width:0;min-height:0;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;overflow:hidden}\n.set.on{border:2px solid var(--accent);background:var(--soft)}\n.sh{flex:none;display:flex;align-items:center;justify-content:space-between;gap:6px;padding:5px 8px 0}\n.no{font-size:11px;font-weight:700;color:var(--muted)}\n.tag{font-size:11px;padding:1px 7px;border-radius:99px;background:var(--accent);color:var(--on-accent);font-weight:600;white-space:nowrap}\n.tag.off{background:transparent;color:var(--muted);border:1px solid var(--line);font-weight:400}\n.sb{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px;padding:4px 8px 6px}\n.f{min-width:0}\n.fl{display:flex;justify-content:space-between;gap:6px;font-size:10px;color:var(--muted);letter-spacing:.04em}\n.fl em{font-style:normal}\n.f p{margin:1px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}\n.nil{display:block;margin-top:1px;color:var(--muted);font-size:12px}\n.ft p{font-weight:600;font-size:13px}\n.fh p{font-weight:800;font-size:15px;line-height:1.3;padding:5px 8px;border-left:4px solid var(--accent);border-radius:4px;background:var(--soft)}\n.set.on .fh p{background:var(--panel-paper)}\n.fi p{font-size:12px;color:var(--muted)}\n.sa{flex:none;display:flex;gap:6px;padding:0 8px 8px}\n.sa .btn{flex:1}\n.fld{display:flex;flex-direction:column;gap:3px;font-size:12px;color:var(--muted);flex:none}\n.fld input,.fld textarea{font:inherit;font-size:13px;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px;padding:6px 8px;width:100%;min-width:0;resize:vertical}\n.fld input:focus,.fld textarea:focus{outline:2px solid var(--accent);outline-offset:0}\n.form{display:flex;flex-direction:column;gap:8px}\n.hint{margin:0;font-size:11px;color:var(--muted)}\n.delrow{display:flex;flex-direction:column;gap:6px;font-size:12px;border:1px solid var(--ink);border-radius:8px;padding:6px 8px}\n.row{display:flex;gap:6px}\n\n/* 3x3\uff1a\u7d27\u51d1 */\n.card[data-size=\"3x3\"]{padding:6px;font-size:12px}\n.card[data-size=\"3x3\"] .view{gap:4px}\n.card[data-size=\"3x3\"] .fh p{font-size:14px}\n.card[data-size=\"3x3\"] .btn{min-height:26px;padding:4px 8px}\n\n/* 6x3\uff1a\u65b9\u6848\u5e76\u6392\uff0c\u6a2a\u5411\u6ed1\u52a8\u6bd4\u8f83 */\n.card[data-size=\"6x3\"] .sets{flex-direction:row;overflow-x:auto;overflow-y:hidden;align-items:stretch}\n.card[data-size=\"6x3\"] .set{flex:0 0 170px;width:170px}\n.card[data-size=\"6x3\"] .sb{overflow-y:auto}\n.card[data-size=\"6x3\"] .empty{overflow:auto}\n\n/* 3x6\uff1a\u5355\u5217\u7eb5\u5411 */\n.card[data-size=\"3x6\"] .sets{flex-direction:column}\n\n/* 6x6\uff1a\u4e24\u5217\u5e76\u6392 */\n.card[data-size=\"6x6\"] .sets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;gap:8px}\n.card[data-size=\"6x6\"] .fh p{font-size:16px}\n";
function mk(c,tag,attrs,...kids){
  return c.el(tag,attrs||{},...kids.flat().filter(function(x){return x!=null&&x!==false&&x!==''}));
}
function vids(s){return s&&Array.isArray(s.videos)?s.videos:[]}
function setsOf(v){return v&&Array.isArray(v.sets)?v.sets:[]}
function curVid(c){
  var id=c.ui.vid;
  return id?(vids(c.state).find(function(v){return v.id===id})||null):null;
}
function mg(a,b){return Object.assign({},a,b)}
function mapVid(s,id,f){
  return mg(s,{videos:vids(s).map(function(v){return v.id===id?f(v):v})});
}
function nlen(t){return Array.from(t||'').length}
function save(c,fn,nextUi){
  var p=nextUi?c.commit(fn,nextUi):c.update(fn);
  return Promise.resolve(p).catch(function(){
    c.ui.err='保存失败，已保留原数据，请重试';
    c.redraw();
    return false;
  });
}
function go(c,patch){
  Object.assign(c.ui,{err:''},patch);
  c.redraw();
}
function btn(c,label,fn,cls,extra){
  return mk(c,'button',Object.assign({type:'button','class':'btn '+(cls||''),onclick:fn},extra||{}),label);
}
function errBar(c){
  return c.ui.err?mk(c,'div',{'class':'err',role:'alert'},'⚠ '+c.ui.err):null;
}
function pickedSet(v){
  return setsOf(v).find(function(x){return x.id===v.pickedId})||null;
}
function pickedText(v){
  var p=pickedSet(v);
  if(!p)return '未选定';
  var i=setsOf(v).indexOf(p)+1;
  return '已选 方案'+i+(p.title?'：'+p.title:'');
}
function vList(c){
  const E=(t,a,...k)=>mk(c,t,a,...k);
  const vs=vids(c.state);
  const rows=vs.map(function(v){
    const n=setsOf(v).length;
    return E('button',{type:'button','class':'vrow'+(v.pickedId?' has':''),onclick:function(){go(c,{vid:v.id})}},
      E('span',{'class':'vn'},v.name||'未命名视频'),
      E('span',{'class':'vm'},n+' 套 · '+pickedText(v)),
      E('span',{'class':'chev','aria-hidden':'true'},'›'));
  });
  const empty=E('div',{'class':'empty'},
    E('b',{},'还没有视频'),
    E('span',{},'先新增一条视频，再为它存几套标题、封面短句和画面想法，并排比较后选定。'));
  return E('div',{'class':'view'},
    E('div',{'class':'head'},
      E('div',{'class':'ttl'},E('b',{},'标题封面备选'),E('span',{},vs.length?vs.length+' 条视频':'暂无视频')),
      btn(c,'＋ 视频',function(){go(c,{form:{kind:'video',draft:{name:''}}})},'pri sm')),
    errBar(c),
    E('div',{'class':'scroll list'},rows.length?rows:empty));
}

function setCard(c,v,x,i){
  const E=(t,a,...k)=>mk(c,t,a,...k);
  const on=v.pickedId===x.id;
  const field=function(lab,txt,cls,cnt){
    return E('div',{'class':'f '+cls},
      E('span',{'class':'fl'},lab,cnt?E('em',{},cnt+' 字'):null),
      txt?E('p',{},txt):E('i',{'class':'nil'},'（未填）'));
  };
  return E('article',{'class':'set'+(on?' on':'')},
    E('div',{'class':'sh'},
      E('span',{'class':'no'},'方案 '+(i+1)),
      E('span',{'class':'tag'+(on?'':' off')},on?'✓ 已选':'备选')),
    E('div',{'class':'sb'},
      field('标题',x.title,'ft',nlen(x.title)),
      field('封面短句',x.hook,'fh',nlen(x.hook)),
      field('画面想法',x.idea,'fi',0)),
    E('div',{'class':'sa'},
      btn(c,on?'取消选用':'选用',function(){
        save(c,function(s){
          return mapVid(s,v.id,function(vv){return mg(vv,{pickedId:vv.pickedId===x.id?null:x.id})});
        });
      },on?'':'pri'),
      btn(c,'编辑',function(){
        go(c,{form:{kind:'set',vid:v.id,id:x.id,draft:{title:x.title||'',hook:x.hook||'',idea:x.idea||''}}});
      })));
}
function vDetail(c){
  const E=(t,a,...k)=>mk(c,t,a,...k);
  const v=curVid(c);
  const ss=setsOf(v);
  const head=E('div',{'class':'head'},
    btn(c,'‹',function(){go(c,{vid:null})},'ico',{'aria-label':'返回视频列表'}),
    E('div',{'class':'ttl'},E('b',{},v.name||'未命名视频'),E('span',{},ss.length+' 套 · '+pickedText(v))),
    btn(c,'编辑',function(){go(c,{form:{kind:'video',id:v.id,draft:{name:v.name||''}}})},'sm'));
  const body=ss.length
    ?E('div',{'class':'sets'},ss.map(function(x,i){return setCard(c,v,x,i)}))
    :E('div',{'class':'empty'},
        E('b',{},'这条视频还没有方案'),
        E('span',{},'每套方案可存标题、封面短句和画面想法，几套放在一起比较。'));
  return E('div',{'class':'view'},
    head,
    errBar(c),
    body,
    E('div',{'class':'foot'},
      btn(c,'＋ 新增一套方案',function(){
        go(c,{form:{kind:'set',vid:v.id,draft:{title:'',hook:'',idea:''}}});
      },'pri wide')));
}

function doSave(c){
  const f=c.ui.form;
  if(!f||f.busy)return;
  const d=f.draft;
  const nextUi=mg(c.ui,{form:null,err:''});
  var fn;
  if(f.kind==='video'){
    const name=(d.name||'').trim();
    if(!name){f.msg='请填写视频名称';c.redraw();return}
    if(f.id){
      fn=function(s){return mapVid(s,f.id,function(v){return mg(v,{name:name})})};
    }else{
      const id=c.uid();
      nextUi.vid=id;
      fn=function(s){
        return mg(s,{videos:vids(s).concat([{id:id,name:name,created:c.day(),pickedId:null,sets:[]}])});
      };
    }
  }else{
    const t=(d.title||'').trim(),h=(d.hook||'').trim(),i=(d.idea||'').trim();
    if(!t&&!h&&!i){f.msg='标题、封面短句、画面想法至少填一项';c.redraw();return}
    const vid=f.vid;
    if(f.id){
      fn=function(s){
        return mapVid(s,vid,function(v){
          return mg(v,{sets:setsOf(v).map(function(x){return x.id===f.id?mg(x,{title:t,hook:h,idea:i}):x})});
        });
      };
    }else{
      const sid=c.uid();
      fn=function(s){
        return mapVid(s,vid,function(v){
          return mg(v,{sets:setsOf(v).concat([{id:sid,title:t,hook:h,idea:i,created:c.day()}])});
        });
      };
    }
  }
  f.busy=true;
  save(c,fn,nextUi).then(function(ok){
    if(ok===false&&c.ui.form){c.ui.form.busy=false;c.redraw()}
  });
}
function doDel(c){
  const f=c.ui.form;
  if(!f||f.busy)return;
  f.busy=true;
  var fn,nextUi=mg(c.ui,{form:null,err:''});
  if(f.kind==='video'){
    nextUi.vid=null;
    fn=function(s){return mg(s,{videos:vids(s).filter(function(v){return v.id!==f.id})})};
  }else{
    fn=function(s){
      return mapVid(s,f.vid,function(v){
        return mg(v,{
          sets:setsOf(v).filter(function(x){return x.id!==f.id}),
          pickedId:v.pickedId===f.id?null:v.pickedId
        });
      });
    };
  }
  save(c,fn,nextUi).then(function(ok){
    if(ok===false&&c.ui.form){c.ui.form.busy=false;c.redraw()}
  });
}
function vForm(c){
  const E=(t,a,...k)=>mk(c,t,a,...k);
  const f=c.ui.form;
  const isSet=f.kind==='set';
  const editing=!!f.id;
  const field=function(key,lab,ph,area,req){
    const attrs={value:f.draft[key]||'',placeholder:ph,
      oninput:function(ev){f.draft[key]=ev.target.value}};
    if(area){attrs.rows=5}
    else{
      attrs.type='text';
      attrs.onkeydown=function(ev){if(ev.key==='Enter'){ev.preventDefault();doSave(c)}};
    }
    return E('label',{'class':'fld'},E('span',{},lab+(req?'（必填）':'')),E(area?'textarea':'input',attrs));
  };
  const fields=isSet?[
    field('title','标题','这套方案的视频标题',false,false),
    field('hook','封面短句','封面上的大字短句',false,false),
    field('idea','画面想法','封面画面、构图、人物或道具的想法',true,false),
    E('p',{'class':'hint'},'三项至少填一项；不填的会显示为「未填」。')
  ]:[
    field('name','视频名称','给这条视频起个名字',false,true)
  ];
  const what=isSet?'这套方案':'这条视频及其全部方案';
  const del=editing?(f.confirm
    ?E('div',{'class':'delrow',role:'alert'},
        E('span',{},'⚠ 确认删除'+what+'？不可恢复。'),
        E('div',{'class':'row'},
          btn(c,'确认删除',function(){doDel(c)},'strong',{disabled:!!f.busy}),
          btn(c,'算了',function(){f.confirm=false;c.redraw()})))
    :btn(c,isSet?'删除这套方案':'删除这条视频',function(){f.confirm=true;c.redraw()},'link')):null;
  return E('div',{'class':'view'},
    E('div',{'class':'head'},
      btn(c,'‹',function(){go(c,{form:null})},'ico',{'aria-label':'返回'}),
      E('div',{'class':'ttl'},E('b',{},(editing?'编辑':'新增')+(isSet?'方案':'视频')))),
    errBar(c),
    f.msg?E('div',{'class':'err',role:'alert'},'⚠ '+f.msg):null,
    E('div',{'class':'scroll form'},fields,del),
    E('div',{'class':'foot two'},
      btn(c,'取消',function(){go(c,{form:null})}),
      btn(c,f.busy?'保存中…':'保存',function(){doSave(c)},'pri',{disabled:!!f.busy})));
}
function mount(ctx){
  const root=ctx.root;
  const view=ctx.ui.form?vForm(ctx):(curVid(ctx)?vDetail(ctx):vList(ctx));
  root.appendChild(view);
}

